<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import api from '../api/client'
import { useToastStore } from '../stores/toasts'
import { formatDateCourt, formatMontant } from '../utils/format'
import PageHeader from '../components/ui/PageHeader.vue'
import Modal from '../components/ui/Modal.vue'
import EmptyState from '../components/ui/EmptyState.vue'
import Icon from '../components/ui/Icon.vue'

const toasts=useToastStore(); const devis=ref([]); const clients=ref([]); const produits=ref([]); const loading=ref(true); const erreur=ref(''); const filtre=ref('tous'); const modal=ref(false); const soumission=ref(false)
const form=reactive({client_id:'',date_validite:'',note:'',lignes:[{produit_id:'',quantite:1,prix_unitaire:'',remise_pourcentage:0}]})
const liste=computed(()=>filtre.value==='tous'?devis.value:devis.value.filter(d=>d.statut===filtre.value)); const labels={brouillon:'Brouillon',envoye:'Envoye',accepte:'Accepte',refuse:'Refuse',transforme:'Transforme'}; const tons={accepte:'success',refuse:'danger',envoye:'warning'}
async function charger(){loading.value=true;try{const [d,c,p]=await Promise.all([api.get('/devis'),api.get('/clients'),api.get('/produits')]);devis.value=d.data;clients.value=c.data;produits.value=p.data}catch(e){erreur.value=e.response?.data?.message||'Chargement impossible'}finally{loading.value=false}}
function ouvrir(){Object.assign(form,{client_id:'',date_validite:'',note:'',lignes:[{produit_id:'',quantite:1,prix_unitaire:'',remise_pourcentage:0}]});modal.value=true} function ajouter(){form.lignes.push({produit_id:'',quantite:1,prix_unitaire:'',remise_pourcentage:0})} function retirer(i){if(form.lignes.length>1)form.lignes.splice(i,1)} function selectionProduit(l){const p=produits.value.find(x=>x.id===Number(l.produit_id));if(p&&l.prix_unitaire==='')l.prix_unitaire=Number(p.prix_vente)} const total=computed(()=>form.lignes.reduce((s,l)=>s+(Number(l.quantite)||0)*(Number(l.prix_unitaire)||0)*(1-(Number(l.remise_pourcentage)||0)/100),0))
async function creer(){soumission.value=true;try{await api.post('/devis',form);modal.value=false;toasts.succes('Devis cree en brouillon');await charger()}catch(e){toasts.erreur(e.response?.data?.message||'Creation impossible')}finally{soumission.value=false}} async function action(d,nom){try{const {data}=await api.post(`/devis/${d.id}/${nom}`);toasts.succes(nom==='convertir'?`Commande ${data.numero} creee`:'Statut mis a jour');await charger()}catch(e){toasts.erreur(e.response?.data?.message||'Action impossible')}}
onMounted(charger)
</script>
<template><div><PageHeader title="Devis et commandes" subtitle="Proposez, faites accepter puis transformez en commande sans modifier les prix historiques."><template #actions><button class="primary" @click="ouvrir"><Icon name="plus" :size="15"/> Nouveau devis</button></template></PageHeader><p v-if="erreur" class="alert alert-danger">{{erreur}}</p><div class="tabs mb-4"><button v-for="s in ['tous','brouillon','envoye','accepte','refuse','transforme']" :key="s" :class="{active:filtre===s}" @click="filtre=s">{{s==='tous'?'Tous':labels[s]}}</button></div><div class="card"><div class="card-body card-body-flush"><p v-if="loading" class="muted" style="padding:16px">Chargement...</p><EmptyState v-else-if="!liste.length" icon="receipt" title="Aucun devis" desc="Creez votre premier devis client."/><div v-else class="table-wrap"><table class="table-cards"><thead><tr><th>Devis</th><th>Client</th><th>Total</th><th>Statut</th><th class="td-actions">Actions</th></tr></thead><tbody><tr v-for="d in liste" :key="d.id"><td><div class="td-strong">{{d.numero}}</div><div class="small muted">{{formatDateCourt(d.created_at)}}</div></td><td>{{d.client_nom}}</td><td>{{formatMontant(d.montant_total)}}</td><td><span class="badge" :class="tons[d.statut]">{{labels[d.statut]}}</span></td><td class="td-actions"><button v-if="d.statut==='brouillon'" class="btn-sm" @click="action(d,'envoyer')">Envoyer</button><button v-if="d.statut==='envoye'" class="btn-sm" @click="action(d,'accepter')">Accepter</button><button v-if="d.statut==='envoye'" class="btn-sm btn-ghost" style="color:var(--danger)" @click="action(d,'refuser')">Refuser</button><button v-if="d.statut==='accepte'" class="btn-sm primary" @click="action(d,'convertir')">Creer commande</button></td></tr></tbody></table></div></div></div><Modal v-if="modal" title="Nouveau devis" @close="modal=false"><form id="devis-form" class="stack" @submit.prevent="creer"><div class="field-row"><div class="field"><label>Client</label><select v-model="form.client_id" required><option value="">Choisir</option><option v-for="c in clients" :key="c.id" :value="c.id">{{c.nom}} — {{c.code}}</option></select></div><div class="field"><label>Valide jusqu'au</label><input v-model="form.date_validite" type="date"/></div></div><div class="stack"><div v-for="(l,i) in form.lignes" :key="i" class="card" style="padding:10px"><div class="field-row"><div class="field"><label>Produit</label><select v-model="l.produit_id" required @change="selectionProduit(l)"><option value="">Choisir</option><option v-for="p in produits" :key="p.id" :value="p.id">{{p.nom}}</option></select></div><div class="field"><label>Qte</label><input v-model="l.quantite" type="number" min="0.01" step="0.01" required/></div><div class="field"><label>Prix unitaire</label><input v-model="l.prix_unitaire" type="number" min="0" required/></div><div class="field"><label>Remise %</label><input v-model="l.remise_pourcentage" type="number" min="0" max="100"/></div></div><button type="button" class="btn-sm btn-ghost" style="color:var(--danger)" @click="retirer(i)">Retirer</button></div><button type="button" class="btn-sm" @click="ajouter"><Icon name="plus" :size="14"/> Ajouter une ligne</button></div><div class="field"><label>Note</label><textarea v-model="form.note" rows="2"/></div><p class="alert alert-info">Total estime : <strong>{{formatMontant(total)}}</strong></p></form><template #footer><button @click="modal=false">Annuler</button><button class="primary" form="devis-form" :disabled="soumission">{{soumission?'Creation...':'Creer le devis'}}</button></template></Modal></div></template>
